import {createFormValidation} from './form-validation.mjs';
import {riskSummary} from './risks.mjs';
import {costBreakdown,resourcePortfolio,safeSourceUrl,sourceTypes} from './resources.mjs';
import {renderResourceDetails,renderResourceEditor,readResourceEditor,bindResourceEditor,sourceReference} from './resource-ui.mjs';
import {examples,evidence,strategicFit,calculate,sortMeasures,scenario} from './model.mjs';
import {renderRoadmap,bindRoadmap,measureRoadmapFields,readMeasureRoadmapFields} from './roadmap-ui.mjs';
const $=id=>document.getElementById(id);
const number=(v,d=0)=>new Intl.NumberFormat('nb-NO',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v);
const money=v=>number(v)+' kr';
const compact=v=>Math.abs(v)>=1000000?number(v/1000000,2)+' mill.':Math.abs(v)>=1000?number(v/1000,0)+' tusen':number(v);
const pp=v=>number(v,2)+' pp';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=t=>`<span class="badge evidence-${t.confidence}">${evidence[t.confidence].label}</span>`;
const fitBadge=t=>`<span class="badge fit-${t.strategicFit}">${strategicFit[t.strategicFit].label}</span>`;
let productCustomers=250000;
let items=structuredClone(examples),selected=items[0].id,editing=null,deleteArmed=false;
const formValidation=createFormValidation($('form'),readDraft);
function render(){
 renderProductWarnings();
 const sorted=sortMeasures(items,$('sort').value);const totals=items.reduce((a,t)=>{const c=calculate(t);a.net+=c.net;a.low+=scenario(t,'low').net;a.high+=scenario(t,'high').net;a.retained+=c.retained;a.cost+=c.cost;return a},{net:0,low:0,high:0,retained:0,cost:0});
 const cards=[['Forventet nettoverdi',compact(totals.net)+' kr','Sum av enkeltstående tiltak','highlight'],['Beholdte kunder',number(totals.retained),'Forventet · før korreksjon for overlapp',''],['Tiltakskostnad, første år',compact(totals.cost)+' kr','Tjenester, engangsposter og teaminnsats',''],['Tiltak med positivt lavscenario',items.filter(t=>scenario(t,'low').net>0).length+' av '+items.length,'Nettoverdi over null i lavscenarioet','']];
 $('metrics').innerHTML=cards.map(([label,value,note,cl])=>`<div class="metric ${cl}"><span class="metric-label">${label}</span><div class="metric-value">${value}</div><small>${note}</small></div>`).join('');$('count').textContent=items.length;
 $('rows').innerHTML=sorted.length?sorted.map((t,i)=>{const c=calculate(t),risk=riskSummary(t);return `<tr data-id="${esc(t.id)}" class="${selected===t.id?'selected':''}"><td><span class="rank">${String(i+1).padStart(2,'0')}</span></td><td><button class="name-button" data-select="${esc(t.id)}" aria-pressed="${selected===t.id}">${esc(t.name)}</button><div class="segment">${esc(t.segment)}</div></td><td>${badge(t)}</td><td>${fitBadge(t)}</td><td class="risk-cell"><button class="risk-jump ${risk.blocked?'risk-blocked':risk.severe?'risk-attention':''}" data-risk-jump="true">${risk.total?risk.active+(risk.active===1?' åpent forhold':' åpne forhold'):'Ikke registrert'}</button><small>${[risk.blocked?risk.blocked+' blokkert':null,risk.severe?risk.severe+(risk.severe===1?' risiko med høy konsekvens':' risikoer med høy konsekvens'):null].filter(Boolean).join(' · ')}</small></td><td>${number(c.retained,1)}</td><td class="money ${c.net<0?'negative':'positive'}" title="${money(c.net)}">${compact(c.net)} kr</td><td class="range-cell" title="${money(scenario(t,'low').net)} → ${money(scenario(t,'high').net)}">${compact(scenario(t,'low').net)} → ${compact(scenario(t,'high').net)}</td><td class="${c.roi<0?'negative':'positive'}">${c.roi===null?'—':number(c.roi)+' %'}</td><td aria-hidden="true">↗</td></tr>`}).join(''):'<tr><td colspan="10" class="empty">Ingen tiltak ennå. Legg til et tiltak for å starte beregningen.</td></tr>';
 $('analysis').hidden=!items.length;if(items.length)renderDetail();renderCapacity();renderRiskOverview();renderRoadmap();
}
function renderDetail(){const t=items.find(x=>x.id===selected)??items[0];selected=t.id;$('selected-title').textContent=t.name;
 $('evidence-links').innerHTML=(t.sources??[]).length?(t.sources??[]).map(s=>{const url=safeSourceUrl(s.url);return `<div class="evidence-link"><span>${esc(sourceTypes[s.type]??'Dokument')}</span>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:`<strong>${esc(s.title)}</strong>`}<small>${esc(s.version||'Dato ikke oppgitt')} · ${esc(s.note||'Hva kilden underbygger er ikke oppgitt.')}</small></div>`}).join(''):'<p>Ingen dokumentasjon lagt til. Knytt presentasjoner, produktarbeid og analyser til antakelsene.</p>';
 const scenarios=['low','expected','high'].map(k=>scenario(t,k));renderResourceDetails(t);
 const rows=[['Churn-reduksjon',[t.low,t.expected,t.high].map(pp)],['Churn etter tiltak',scenarios.map(c=>number(c.churn,2)+' %')],['Beholdte kunder',scenarios.map(c=>number(c.retained,1))],['Bruttoverdi',scenarios.map(c=>money(c.gross))],['Total kostnad',scenarios.map(c=>money(c.cost))],['Nettoverdi',scenarios.map(c=>money(c.net))]];
 $('scenario-table').innerHTML=`<table class="scenario-table"><thead><tr><th>12 måneder</th><th>Lav</th><th class="expected">Forventet</th><th>Høy</th></tr></thead><tbody>${rows.map(([label,vals],i)=>`<tr><td>${label}</td>${vals.map((v,j)=>`<td class="${j===1?'expected ':''}${i===5?(scenarios[j].net<0?'negative':'positive'):''}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
 $('evidence-box').innerHTML=`<p class="description">${esc(t.description)}</p>${badge(t)} ${fitBadge(t)}<p>${sourceReference(t,t.effectSourceId)}</p><p>${esc(t.evidence||'Ingen kilde eller evidensnotat registrert.')}</p><p><strong>Strategisk fit:</strong> ${esc(t.strategicFitNote||'Ingen strategisk fit-notat registrert.')}</p><p>${number(calculate(t).exposed)} eksponerte kunder · ${number(t.reach,1)} % av ${number(t.customers)} adresserbare (${productCustomers?number(t.customers/productCustomers*100,1)+' %':'—'} av produktets kundebase på ${number(productCustomers)})</p>`;
 const span=t.high-t.low;let min=Math.max(t.baseline-100,Math.min(0,t.low-(span||.2)*.15)),max=Math.min(t.baseline,Math.max(t.high+(span||.2)*.25,.5));if(max===min){min=Math.max(t.baseline-100,min-1);max=Math.min(t.baseline,max+1)}
 $('sensitivity').min=min;$('sensitivity').max=max;$('sensitivity').step='any';$('sensitivity').value=t.expected;$('range-min').textContent=pp(min);$('range-max').textContent=pp(max);updateSensitivity();
}
function updateSensitivity(){const t=items.find(x=>x.id===selected);if(!t)return;const reduction=Number($('sensitivity').value),c=calculate(t,reduction);$('slider-value').textContent=pp(reduction);$('sim-value').textContent=money(c.net);$('sim-value').className=c.net<0?'negative':'positive';$('sim-retained').textContent=number(c.retained,1);
 const be=c.breakEven;$('breakeven').textContent=be===null?'Ingen positiv bruttoverdi mulig med dagens rekkevidde og kundeverdi.':be>t.baseline?`Nullpunkt: ${pp(be)} — overstiger baseline churn og kan ikke nås med dagens antakelser.`:`Nullpunkt ved ${pp(be)} churn-reduksjon.`;
 const lo=Number($('sensitivity').min),hi=Number($('sensitivity').max);const lowNet=calculate(t,lo).net,highNet=calculate(t,hi).net;const ymin=Math.min(lowNet,0),ymax=Math.max(highNet,0),spread=(ymax-ymin)||1;
 const x=v=>65+(v-lo)/(hi-lo)*410,y=v=>142-(v-ymin)/spread*106;let grid='';for(let i=0;i<=2;i++){const v=ymin+spread*i/2;grid+=`<line x1="65" y1="${y(v)}" x2="475" y2="${y(v)}" stroke="#e5ecef" ${Math.abs(v)<.001?'stroke-dasharray="4 4"':''}/><text x="56" y="${y(v)+4}" text-anchor="end">${compact(v)}</text>`}
 const expectedX=x(t.expected);const chartTitle=`Nettoverdi ved churn-reduksjon fra ${pp(lo)} til ${pp(hi)}. Nå ${money(c.net)} ved ${pp(reduction)}.`;
 $('chart').innerHTML=`<div class="chart-wrap"><svg viewBox="0 0 510 180" role="img" aria-label="${esc(chartTitle)}"><text x="65" y="15">NOK</text>${grid}<path d="M ${x(lo)} ${y(lowNet)} L ${x(hi)} ${y(highNet)} L ${x(hi)} ${y(0)} L ${x(lo)} ${y(0)} Z" fill="#e9f4ef" opacity=".65"/><line x1="65" y1="${y(0)}" x2="475" y2="${y(0)}" stroke="#a3b6bc" stroke-dasharray="4 4"/><line x1="${x(lo)}" y1="${y(lowNet)}" x2="${x(hi)}" y2="${y(highNet)}" stroke="#2d7a64" stroke-width="2.5"/><line x1="${expectedX}" x2="${expectedX}" y1="${y(calculate(t).net)}" y2="150" stroke="#94bba8" stroke-dasharray="3 4"/>${[t.low,t.expected,t.high].map((r,i)=>`<circle cx="${x(r)}" cy="${y(calculate(t,r).net)}" r="${i===1?5:3.5}" fill="${i===1?'#285e4d':'#fff'}" stroke="#2d7a64" stroke-width="1.5"/>`).join('')}<circle cx="${x(reduction)}" cy="${y(c.net)}" r="7" fill="#c1ee93" stroke="#21634e" stroke-width="2"/><text x="65" y="166">${pp(lo)}</text><text x="475" y="166" text-anchor="end">${pp(hi)}</text><text x="${expectedX}" y="166" text-anchor="middle" class="dot-label">Forventet</text></svg></div>`;
}
function openEditor(id=null){editing=id;deleteArmed=false;const t=id?items.find(x=>x.id===id):{name:'',description:'',segment:'',customers:Math.min(100000,productCustomers),reach:50,baseline:8,value:6000,low:0,expected:.3,high:.6,cost:0,setup:0,costItems:[],teams:[],sources:[],effectSourceId:'',risks:[],confidence:'hypothesis',evidence:'',strategicFit:'medium',strategicFitNote:'',horizon:'',requires:[],keyResultIds:[]};formValidation.reset();$('form').reset();renderResourceEditor(t);$('roadmap-editor-section').innerHTML=measureRoadmapFields(t,items);Object.entries(t).forEach(([key,value])=>{const el=$('form').elements.namedItem(key);if(el&&!Array.isArray(value))el.value=value});$('editor-title').textContent=id?'Rediger tiltak':'Nytt tiltak';$('delete').hidden=!id;$('delete').textContent='Slett tiltak';$('form-error').textContent='';$('editor').showModal();$('form').elements.namedItem('customers').max=productCustomers;$('form').elements.namedItem('name').focus();}
function closeEditor(){$('editor').close()}
function select(id){selected=id;render();$('live').textContent=`Viser scenarioer for ${items.find(x=>x.id===id).name}.`}
function focusSelected(){document.querySelector(`[data-select="${selected}"]`)?.focus({preventScroll:true})}
 $('rows').addEventListener('click',e=>{const row=e.target.closest('[data-id]');if(row){select(row.dataset.id);focusSelected();if(e.target.closest('[data-risk-jump]'))$('risk-panel').scrollIntoView({block:'start'})}});
 $('edit-risks').addEventListener('click',()=>{openEditor(selected);$('risk-editor-section').scrollIntoView({block:'start'});});
 $('edit-resources').addEventListener('click',()=>{openEditor(selected);$('resource-editor-section').scrollIntoView({block:'start'});});
 $('sort').addEventListener('change',render);$('sensitivity').addEventListener('input',updateSensitivity);$('add').addEventListener('click',()=>openEditor());$('edit').addEventListener('click',()=>openEditor(selected));$('close').addEventListener('click',closeEditor);$('cancel').addEventListener('click',closeEditor);
 function readDraft(){const raw=Object.fromEntries(new FormData($('form')));const t={...raw,...readResourceEditor(),...readMeasureRoadmapFields($('form')),cost:0,setup:0,productCustomers,id:editing??'draft',name:(raw.name??'').trim()};['customers','reach','baseline','value','low','expected','high'].forEach(k=>t[k]=raw[k]?.trim()===''?NaN:Number(raw[k]));return t;}
 $('form').addEventListener('submit',e=>{e.preventDefault();if(!formValidation.check())return;const t=readDraft();if(!editing)t.id=crypto.randomUUID();if(editing)items=items.map(x=>x.id===editing?t:x);else items.push(t);selected=t.id;closeEditor();render();$('live').textContent='Tiltaket er lagret for denne økten.';});
 $('delete').addEventListener('click',()=>{if(!deleteArmed){deleteArmed=true;$('delete').textContent='Bekreft sletting';$('form-error').textContent='Klikk «Bekreft sletting» for å fjerne tiltaket.';return}items=items.filter(x=>x.id!==editing);selected=items[0]?.id;closeEditor();render();$('add').focus();$('live').textContent='Tiltaket er slettet.'});
$('edit-evidence').addEventListener('click',()=>{openEditor(selected);$('source-editor-section').scrollIntoView({block:'start',behavior:'instant'});});
$('product-customers').addEventListener('input',()=>{const el=$('product-customers');if(!el.validity.valid){el.setAttribute('aria-invalid','true');$('product-warning').textContent='Antall kunder må være et heltall mellom 0 og 1 000 000 000. Beregningene bruker sist gyldige kundebase.';return;}el.removeAttribute('aria-invalid');productCustomers=el.valueAsNumber;render();});
$('product-warning').addEventListener('click',e=>{const b=e.target.closest('[data-fix-product]');if(b)openEditor(b.dataset.fixProduct);});
function renderProductWarnings(){const outside=items.filter(t=>t.customers>productCustomers);$('product-warning').innerHTML=outside.length?`<strong>${outside.length} tiltak har flere adresserbare kunder enn produktets kundebase. Rett anslagene før verdiene brukes.</strong>${outside.map(t=>`<button class="error-jump" data-fix-product="${esc(t.id)}">${esc(t.name)}: ${number(t.customers)} kunder – gå til tiltaket ↗</button>`).join('')}`:'';}
bindRoadmap(()=>items,select);
render();

function renderCapacity(){
 const groups=resourcePortfolio(items);$('capacity-count').textContent=groups.length+' team';
 $('capacity-rows').innerHTML=groups.length?groups.map(g=>`<tr><th scope="row">${esc(g.name)}</th><td>${g.measures}</td><td>${number(g.low,1)}</td><td class="expected">${number(g.expected,1)}</td><td>${number(g.high,1)}</td></tr>`).join(''):'<tr><td colspan="5">Ingen team er lagt til ennå.</td></tr>';
}
bindResourceEditor();

function renderRiskOverview(){const summaries=items.map(riskSummary);const sum=k=>summaries.reduce((n,r)=>n+r[k],0);$('risk-overview').innerHTML=`<span>Blokkerte avhengigheter: <strong>${sum('blocked')}</strong></span><span>Åpne risikoer med høy konsekvens: <strong>${sum('severe')}</strong></span><span>Åpne forhold uten ansvarlig: <strong>${sum('unowned')}</strong></span><span>Tiltak uten registrerte forhold: <strong>${summaries.filter(r=>!r.total).length}</strong></span>`;}
